    "about": "\"An unique view in the heart of Paris\" The Hôtel Brighton, built on Rue de Rivoli by Lord Egerton at the beginning of the 19th century, became one of the capital’s leading hotels, attracting many British customers. This district of Paris, which is now the 1st arrondissement, was very popular with British clients on The Grand Tour, an initiatory trip across Europe and sometimes as far as Asia with the aim of completing the artistic and cultural education of the young middle classes. The hotel has preserved a large number of antique elements down the years, beginning with the period mosaic with the words \"Hôtel Brighton\" on the ground beneath the arcades of Rue de Rivoli in front of the hotel. Inside, the marble columns in the hall, the sculpted high reliefs in the bar, the set of antique mirrors and the many French windows, the tall ceilings on the \"noble floors\" and the exposed beams in the rooms on the upper storeys all bear witness to the history of the site and the people who gave it its charm. But what makes the Hôtel Brighton a truly exceptional place is the breathtaking 180° panorama. To the left, the Louvre, once a royal palace, today a museum, the Tuileries Gardens opposite and the Place de la Concorde to the right with the Eiffel Tower in the background. One of your best memories of Paris will be this unique view.",
